-- 律法 AI · PostgreSQL 17 首次建库 DDL（27 张业务表，law schema）
-- 一次性、事务执行；已存在同名表时失败回滚，不覆盖现有结构或数据。
-- 依赖 pgvector 和 pg_trgm；使用 simple 分词作基线，中文分词扩展待部署时确认。

BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;

CREATE SCHEMA IF NOT EXISTS law;

SET LOCAL search_path = law, public;

CREATE TABLE law."users" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "display_name" varchar(50) NOT NULL,
  "avatar_url" text,
  "status" varchar(16) NOT NULL DEFAULT 'active',
  "last_login_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "deleted_at" timestamptz,
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('active', 'disabled', 'deleted'))
);

CREATE TABLE law."user_identities" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint NOT NULL,
  "provider" varchar(20) NOT NULL,
  "provider_uid" varchar(128) NOT NULL,
  "union_id" varchar(128),
  "verified_at" timestamptz,
  "last_used_at" timestamptz,
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE TABLE law."user_sessions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint NOT NULL,
  "refresh_token_hash" char(64) NOT NULL,
  "device_label" varchar(100),
  "device_info" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "ip" inet,
  "expires_at" timestamptz NOT NULL,
  "revoked_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "last_seen_at" timestamptz,
  PRIMARY KEY ("id"),
  UNIQUE ("refresh_token_hash")
);

CREATE TABLE law."user_profiles" (
  "user_id" bigint NOT NULL,
  "role_type" varchar(16) NOT NULL,
  "real_name" varchar(50) NOT NULL,
  "company_name" varchar(200),
  "position" varchar(100),
  "industry" varchar(100),
  "organization_name" varchar(200),
  "legal_role" varchar(50),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("user_id"),
  CHECK ("role_type" IN ('individual', 'enterprise', 'legal'))
);

CREATE TABLE law."organizations" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(200) NOT NULL,
  "industry" varchar(100),
  "owner_user_id" bigint NOT NULL,
  "status" varchar(16) NOT NULL DEFAULT 'active',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('active', 'disabled'))
);

CREATE TABLE law."organization_members" (
  "org_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "role" varchar(16) NOT NULL DEFAULT 'member',
  "status" varchar(16) NOT NULL DEFAULT 'active',
  "joined_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("org_id", "user_id"),
  CHECK ("role" IN ('owner', 'admin', 'member')),
  CHECK ("status" IN ('invited', 'active', 'removed'))
);

CREATE TABLE law."legal_documents" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "doc_type" varchar(20) NOT NULL,
  "version" varchar(20) NOT NULL,
  "title" varchar(200) NOT NULL,
  "content" text NOT NULL,
  "effective_at" timestamptz NOT NULL,
  "published_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE TABLE law."user_consents" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint NOT NULL,
  "document_id" bigint NOT NULL,
  "agreed_at" timestamptz NOT NULL DEFAULT now(),
  "ip" inet,
  "user_agent" text,
  PRIMARY KEY ("id")
);

CREATE TABLE law."cases" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "owner_user_id" bigint NOT NULL,
  "org_id" bigint,
  "title" varchar(200) NOT NULL,
  "case_type" varchar(20) NOT NULL DEFAULT 'civil',
  "procedure" varchar(20) NOT NULL DEFAULT 'first_instance',
  "analysis_status" varchar(20) NOT NULL DEFAULT 'not_analyzed',
  "evidence_upload_status" varchar(20) NOT NULL DEFAULT 'not_uploaded',
  "win_rate" numeric(5,2),
  "win_rate_updated_at" timestamptz,
  "status" varchar(16) NOT NULL DEFAULT 'active',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "deleted_at" timestamptz,
  PRIMARY KEY ("id"),
  CHECK ("case_type" IN ('civil', 'criminal', 'administrative', 'other')),
  CHECK ("procedure" IN ('first_instance', 'second_instance', 'retrial', 'enforcement', 'arbitration', 'other')),
  CHECK ("analysis_status" IN ('not_analyzed', 'analyzing', 'analyzed', 'failed')),
  CHECK ("evidence_upload_status" IN ('not_uploaded', 'partial', 'completed')),
  CHECK ("win_rate" BETWEEN 0 AND 100),
  CHECK ("status" IN ('active', 'archived', 'deleted'))
);

CREATE TABLE law."case_parties" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "case_id" bigint NOT NULL,
  "party_role" varchar(20) NOT NULL,
  "party_type" varchar(12) NOT NULL,
  "name" varchar(200) NOT NULL,
  "id_no_masked" varchar(32),
  "phone_masked" varchar(32),
  "address" text,
  "sort_order" smallint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE TABLE law."evidence_requirements" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "case_id" bigint NOT NULL,
  "title" varchar(200) NOT NULL,
  "category" varchar(20) NOT NULL,
  "purpose" text,
  "collection_channel" text,
  "collection_method" text,
  "precautions" text,
  "status" varchar(16) NOT NULL DEFAULT 'required',
  "source" varchar(8) NOT NULL DEFAULT 'ai',
  "analysis_id" bigint,
  "sort_order" smallint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("category" IN ('written', 'electronic', 'photo_video', 'audio', 'physical')),
  CHECK ("status" IN ('required', 'collecting', 'collected', 'waived')),
  CHECK ("source" IN ('ai', 'manual'))
);

CREATE TABLE law."evidence_items" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "case_id" bigint NOT NULL,
  "requirement_id" bigint,
  "category" varchar(20) NOT NULL,
  "title" varchar(200) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'ai_analyzing',
  "status_reason" text,
  "description" text,
  "source" varchar(100),
  "occurred_on" date,
  "uploader_user_id" bigint,
  "contact_name" varchar(50),
  "contact_phone_masked" varchar(32),
  "reviewed_by" bigint,
  "reviewed_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("category" IN ('written', 'electronic', 'photo_video', 'audio', 'physical')),
  CHECK ("status" IN ('ai_analyzing', 'ai_passed', 'ai_failed', 'lawyer_pending', 'lawyer_rejected'))
);

CREATE TABLE law."files" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "case_id" bigint,
  "uploaded_by" bigint,
  "storage_provider" varchar(16) NOT NULL DEFAULT 's3',
  "bucket" varchar(100) NOT NULL,
  "object_key" text NOT NULL,
  "original_name" varchar(255) NOT NULL,
  "mime_type" varchar(100) NOT NULL,
  "size_bytes" bigint NOT NULL,
  "sha256" char(64),
  "status" varchar(16) NOT NULL DEFAULT 'uploading',
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("size_bytes" > 0),
  CHECK ("status" IN ('uploading', 'available', 'quarantined', 'failed', 'deleted'))
);

CREATE TABLE law."evidence_item_files" (
  "evidence_item_id" bigint NOT NULL,
  "file_id" bigint NOT NULL,
  "case_id" bigint NOT NULL,
  "sort_order" smallint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("evidence_item_id", "file_id")
);

CREATE TABLE law."case_documents" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "case_id" bigint NOT NULL,
  "file_id" bigint NOT NULL,
  "title" varchar(255) NOT NULL,
  "category" varchar(20) NOT NULL DEFAULT 'other',
  "ai_classified" boolean NOT NULL DEFAULT false,
  "classification_confidence" numeric(4,3),
  "uploaded_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("category" IN ('case_procedure', 'court_record', 'communication', 'other')),
  CHECK ("classification_confidence" BETWEEN 0 AND 1)
);

CREATE TABLE law."doc_chunks" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "file_id" bigint NOT NULL,
  "case_id" bigint NOT NULL,
  "chunk_index" int NOT NULL,
  "content" text NOT NULL,
  "page_no" int,
  "char_start" int,
  "char_end" int,
  "token_count" int,
  "embedding" public.vector(1536),
  "embedding_model" varchar(100),
  "search_vector" tsvector GENERATED ALWAYS AS (to_tsvector('pg_catalog.simple'::regconfig, content)) STORED,
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("chunk_index" >= 0)
);

CREATE TABLE law."case_analyses" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "case_id" bigint NOT NULL,
  "analysis_type" varchar(30) NOT NULL,
  "status" varchar(16) NOT NULL DEFAULT 'pending',
  "content" jsonb,
  "schema_version" varchar(20) NOT NULL DEFAULT '1.0',
  "model" varchar(100),
  "prompt_version_id" bigint,
  "source_fingerprint" char(64),
  "input_tokens" int,
  "output_tokens" int,
  "cost_usd" numeric(10,6),
  "error_message" text,
  "created_by" bigint,
  "started_at" timestamptz,
  "completed_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('pending', 'running', 'succeeded', 'failed', 'cancelled'))
);

CREATE TABLE law."analysis_sources" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "analysis_id" bigint NOT NULL,
  "case_id" bigint NOT NULL,
  "chunk_id" bigint,
  "file_id" bigint NOT NULL,
  "weight" numeric(5,4),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE TABLE law."ai_conversations" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint NOT NULL,
  "case_id" bigint,
  "mode" varchar(16) NOT NULL,
  "title" varchar(200) NOT NULL DEFAULT '未命名对话',
  "status" varchar(16) NOT NULL DEFAULT 'active',
  "message_count" int NOT NULL DEFAULT 0,
  "last_message_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "deleted_at" timestamptz,
  PRIMARY KEY ("id"),
  CHECK ("mode" IN ('assistant', 'case_qa')),
  CHECK ("status" IN ('active', 'archived', 'deleted'))
);

CREATE TABLE law."ai_messages" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "conversation_id" bigint NOT NULL,
  "case_id" bigint,
  "seq" int NOT NULL,
  "role" varchar(10) NOT NULL,
  "content" text NOT NULL DEFAULT '',
  "content_type" varchar(12) NOT NULL DEFAULT 'markdown',
  "status" varchar(12) NOT NULL DEFAULT 'completed',
  "model" varchar(100),
  "prompt_version_id" bigint,
  "input_tokens" int,
  "output_tokens" int,
  "cost_usd" numeric(10,6),
  "latency_ms" int,
  "client_message_id" varchar(64),
  "error_code" varchar(50),
  "error_message" text,
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "completed_at" timestamptz,
  PRIMARY KEY ("id"),
  CHECK ("role" IN ('user', 'assistant', 'system', 'tool')),
  CHECK ("content_type" IN ('markdown', 'text', 'json')),
  CHECK ("status" IN ('streaming', 'completed', 'failed', 'cancelled'))
);

CREATE TABLE law."ai_message_files" (
  "message_id" bigint NOT NULL,
  "file_id" bigint NOT NULL,
  "case_id" bigint,
  "sort_order" smallint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("message_id", "file_id")
);

CREATE TABLE law."ai_citations" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "message_id" bigint NOT NULL,
  "chunk_id" bigint,
  "file_id" bigint,
  "case_id" bigint NOT NULL,
  "document_title" varchar(255) NOT NULL,
  "quote" text NOT NULL,
  "page_no" int,
  "rank" smallint NOT NULL,
  "relevance" numeric(5,4),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE TABLE law."ai_feedback" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "message_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "rating" varchar(8) NOT NULL,
  "reason_code" varchar(50),
  "comment" text,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("rating" IN ('like', 'dislike'))
);

CREATE TABLE law."tool_calls" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "conversation_id" bigint NOT NULL,
  "message_id" bigint,
  "run_id" uuid NOT NULL,
  "step_no" smallint NOT NULL,
  "tool_name" varchar(100) NOT NULL,
  "arguments" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "result" jsonb,
  "status" varchar(12) NOT NULL DEFAULT 'pending',
  "error_message" text,
  "idempotency_key" varchar(128),
  "latency_ms" int,
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("idempotency_key"),
  CHECK ("status" IN ('pending', 'running', 'succeeded', 'failed', 'cancelled'))
);

CREATE TABLE law."prompt_versions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "prompt_key" varchar(100) NOT NULL,
  "version" int NOT NULL,
  "content" text NOT NULL,
  "model_default" varchar(100),
  "params" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "status" varchar(10) NOT NULL DEFAULT 'draft',
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CHECK ("version" > 0),
  CHECK ("status" IN ('draft', 'active', 'retired'))
);

CREATE TABLE law."async_jobs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_type" varchar(30) NOT NULL,
  "status" varchar(12) NOT NULL DEFAULT 'queued',
  "resource_type" varchar(30) NOT NULL,
  "resource_id" bigint NOT NULL,
  "payload" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "attempts" smallint NOT NULL DEFAULT 0,
  "max_attempts" smallint NOT NULL DEFAULT 3,
  "last_error" text,
  "idempotency_key" varchar(128),
  "scheduled_at" timestamptz NOT NULL DEFAULT now(),
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("idempotency_key"),
  CHECK ("status" IN ('queued', 'running', 'succeeded', 'failed', 'cancelled', 'dead'))
);

CREATE TABLE law."audit_logs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint,
  "action" varchar(100) NOT NULL,
  "resource_type" varchar(50) NOT NULL,
  "resource_id" bigint,
  "ip" inet,
  "user_agent" text,
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

ALTER TABLE law."user_identities" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."user_sessions" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."user_profiles" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."organizations" ADD FOREIGN KEY ("owner_user_id") REFERENCES law."users" ("id");

ALTER TABLE law."organization_members" ADD FOREIGN KEY ("org_id") REFERENCES law."organizations" ("id");

ALTER TABLE law."organization_members" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."user_consents" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."user_consents" ADD FOREIGN KEY ("document_id") REFERENCES law."legal_documents" ("id");

ALTER TABLE law."cases" ADD FOREIGN KEY ("owner_user_id") REFERENCES law."users" ("id");

ALTER TABLE law."cases" ADD FOREIGN KEY ("org_id") REFERENCES law."organizations" ("id");

ALTER TABLE law."case_parties" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."evidence_requirements" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."evidence_items" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."evidence_items" ADD FOREIGN KEY ("uploader_user_id") REFERENCES law."users" ("id");

ALTER TABLE law."evidence_items" ADD FOREIGN KEY ("reviewed_by") REFERENCES law."users" ("id");

ALTER TABLE law."files" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."files" ADD FOREIGN KEY ("uploaded_by") REFERENCES law."users" ("id");

ALTER TABLE law."evidence_item_files" ADD FOREIGN KEY ("evidence_item_id") REFERENCES law."evidence_items" ("id");

ALTER TABLE law."evidence_item_files" ADD FOREIGN KEY ("file_id") REFERENCES law."files" ("id");

ALTER TABLE law."evidence_item_files" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."case_documents" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."case_documents" ADD FOREIGN KEY ("uploaded_by") REFERENCES law."users" ("id");

ALTER TABLE law."doc_chunks" ADD FOREIGN KEY ("file_id") REFERENCES law."files" ("id");

ALTER TABLE law."doc_chunks" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."case_analyses" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."case_analyses" ADD FOREIGN KEY ("prompt_version_id") REFERENCES law."prompt_versions" ("id");

ALTER TABLE law."case_analyses" ADD FOREIGN KEY ("created_by") REFERENCES law."users" ("id");

ALTER TABLE law."analysis_sources" ADD FOREIGN KEY ("analysis_id") REFERENCES law."case_analyses" ("id");

ALTER TABLE law."analysis_sources" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."ai_conversations" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."ai_conversations" ADD FOREIGN KEY ("case_id") REFERENCES law."cases" ("id");

ALTER TABLE law."ai_messages" ADD FOREIGN KEY ("conversation_id") REFERENCES law."ai_conversations" ("id");

ALTER TABLE law."ai_messages" ADD FOREIGN KEY ("prompt_version_id") REFERENCES law."prompt_versions" ("id");

ALTER TABLE law."ai_message_files" ADD FOREIGN KEY ("message_id") REFERENCES law."ai_messages" ("id");

ALTER TABLE law."ai_message_files" ADD FOREIGN KEY ("file_id") REFERENCES law."files" ("id");

ALTER TABLE law."ai_citations" ADD FOREIGN KEY ("message_id") REFERENCES law."ai_messages" ("id");

ALTER TABLE law."ai_feedback" ADD FOREIGN KEY ("message_id") REFERENCES law."ai_messages" ("id");

ALTER TABLE law."ai_feedback" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."tool_calls" ADD FOREIGN KEY ("conversation_id") REFERENCES law."ai_conversations" ("id");

ALTER TABLE law."tool_calls" ADD FOREIGN KEY ("message_id") REFERENCES law."ai_messages" ("id");

ALTER TABLE law."prompt_versions" ADD FOREIGN KEY ("created_by") REFERENCES law."users" ("id");

ALTER TABLE law."audit_logs" ADD FOREIGN KEY ("user_id") REFERENCES law."users" ("id");

ALTER TABLE law."cases" ADD UNIQUE (id, org_id);

ALTER TABLE law."evidence_requirements" ADD UNIQUE (id, case_id);

ALTER TABLE law."evidence_items" ADD UNIQUE (id, case_id);

ALTER TABLE law."files" ADD UNIQUE (id, case_id);

ALTER TABLE law."doc_chunks" ADD UNIQUE (id, case_id);

ALTER TABLE law."case_analyses" ADD UNIQUE (id, case_id);

ALTER TABLE law."ai_conversations" ADD UNIQUE (id, case_id);

ALTER TABLE law."ai_messages" ADD UNIQUE (id, case_id);

ALTER TABLE law."organizations" ADD FOREIGN KEY (id, owner_user_id) REFERENCES law.organization_members (org_id, user_id) DEFERRABLE INITIALLY DEFERRED;

CREATE UNIQUE INDEX ON law."organization_members" (org_id) WHERE role = 'owner' AND status = 'active';

ALTER TABLE law."evidence_items" ADD FOREIGN KEY (requirement_id, case_id) REFERENCES law.evidence_requirements (id, case_id);

ALTER TABLE law."evidence_requirements" ADD FOREIGN KEY (analysis_id, case_id) REFERENCES law.case_analyses (id, case_id);

ALTER TABLE law."evidence_item_files" ADD FOREIGN KEY (evidence_item_id, case_id) REFERENCES law.evidence_items (id, case_id);

ALTER TABLE law."evidence_item_files" ADD FOREIGN KEY (file_id, case_id) REFERENCES law.files (id, case_id);

ALTER TABLE law."case_documents" ADD FOREIGN KEY (file_id, case_id) REFERENCES law.files (id, case_id);

ALTER TABLE law."doc_chunks" ADD FOREIGN KEY (file_id, case_id) REFERENCES law.files (id, case_id);

ALTER TABLE law."analysis_sources" ADD FOREIGN KEY (analysis_id, case_id) REFERENCES law.case_analyses (id, case_id);

ALTER TABLE law."analysis_sources" ADD FOREIGN KEY (chunk_id, case_id) REFERENCES law.doc_chunks (id, case_id);

ALTER TABLE law."analysis_sources" ADD FOREIGN KEY (file_id, case_id) REFERENCES law.files (id, case_id);

ALTER TABLE law."ai_messages" ADD FOREIGN KEY (conversation_id, case_id) REFERENCES law.ai_conversations (id, case_id);

ALTER TABLE law."ai_message_files" ADD FOREIGN KEY (message_id, case_id) REFERENCES law.ai_messages (id, case_id);

ALTER TABLE law."ai_message_files" ADD FOREIGN KEY (file_id, case_id) REFERENCES law.files (id, case_id);

ALTER TABLE law."ai_citations" ADD FOREIGN KEY (message_id, case_id) REFERENCES law.ai_messages (id, case_id);

ALTER TABLE law."ai_citations" ADD FOREIGN KEY (chunk_id, case_id) REFERENCES law.doc_chunks (id, case_id);

ALTER TABLE law."ai_citations" ADD FOREIGN KEY (file_id, case_id) REFERENCES law.files (id, case_id);

ALTER TABLE law."ai_conversations" ADD CHECK ((mode = 'assistant' AND case_id IS NULL) OR (mode = 'case_qa' AND case_id IS NOT NULL));

CREATE INDEX ON law."users" USING btree (status, created_at DESC);

