-- 字典与角色档案完整性。
ALTER TABLE law.user_identities ADD CHECK (provider IN ('phone', 'wechat_mini', 'alipay_mini', 'apple'));
ALTER TABLE law.legal_documents ADD CHECK (doc_type IN ('user_service', 'privacy_policy', 'disclaimer'));
ALTER TABLE law.case_parties ADD CHECK (party_role IN ('plaintiff', 'defendant', 'third_party', 'applicant', 'respondent', 'other'));
ALTER TABLE law.case_parties ADD CHECK (party_type IN ('person', 'company', 'organization'));
ALTER TABLE law.files ADD CHECK (storage_provider IN ('s3', 'cos', 'oss'));
ALTER TABLE law.files ADD CHECK (case_id IS NOT NULL OR uploaded_by IS NOT NULL);
ALTER TABLE law.user_profiles ADD CONSTRAINT user_profiles_role_fields_check CHECK (
  btrim(real_name) <> '' AND (
    (role_type = 'individual' AND company_name IS NULL AND position IS NULL AND industry IS NULL AND organization_name IS NULL AND legal_role IS NULL)
    OR (role_type = 'enterprise'
      AND company_name IS NOT NULL AND btrim(company_name) <> ''
      AND position IS NOT NULL AND btrim(position) <> ''
      AND industry IS NOT NULL AND btrim(industry) <> ''
      AND organization_name IS NULL AND legal_role IS NULL)
    OR (role_type = 'legal'
      AND organization_name IS NOT NULL AND btrim(organization_name) <> ''
      AND legal_role IS NOT NULL AND btrim(legal_role) <> ''
      AND company_name IS NULL AND position IS NULL AND industry IS NULL)
  )
);
ALTER TABLE law.evidence_requirements ADD CHECK (source <> 'ai' OR analysis_id IS NOT NULL);
ALTER TABLE law.case_analyses ADD CHECK (analysis_type IN ('win_rate', 'case_summary', 'timeline', 'judicial_reasoning', 'dispute_focus', 'evidence_chain', 'evidence_list'));
ALTER TABLE law.async_jobs ADD CHECK (job_type IN ('ocr', 'document_parse', 'embedding', 'file_scan', 'case_analysis', 'evidence_analysis'));
ALTER TABLE law.async_jobs ADD CHECK (resource_type IN ('file', 'case', 'analysis', 'evidence_item'));
ALTER TABLE law.async_jobs ADD CHECK (attempts >= 0 AND max_attempts > 0);
ALTER TABLE law.ai_messages ADD CHECK (seq > 0);
ALTER TABLE law.ai_conversations ADD CHECK (message_count >= 0);

-- chunk/file 必须指向同一份文件，不仅是同一个案件。
ALTER TABLE law.doc_chunks ADD UNIQUE (id, file_id, case_id);
ALTER TABLE law.analysis_sources ADD FOREIGN KEY (chunk_id, file_id, case_id) REFERENCES law.doc_chunks (id, file_id, case_id);
ALTER TABLE law.ai_citations ADD CHECK (chunk_id IS NULL OR file_id IS NOT NULL);
ALTER TABLE law.ai_citations ADD FOREIGN KEY (chunk_id, file_id, case_id) REFERENCES law.doc_chunks (id, file_id, case_id);
ALTER TABLE law.ai_messages ADD UNIQUE (id, conversation_id);
ALTER TABLE law.tool_calls ADD FOREIGN KEY (message_id, conversation_id) REFERENCES law.ai_messages (id, conversation_id);

-- 防止修改上游归属后绕过可空复合外键；需要迁移材料时显式复制记录。
CREATE FUNCTION law.reject_scope_change() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, law AS $$
DECLARE
  column_name text;
BEGIN
  FOREACH column_name IN ARRAY TG_ARGV LOOP
    IF (to_jsonb(NEW) -> column_name) IS DISTINCT FROM (to_jsonb(OLD) -> column_name) THEN
      RAISE EXCEPTION '% 的归属字段 % 不允许变更', TG_TABLE_NAME, column_name USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;
CREATE TRIGGER files_scope_immutable BEFORE UPDATE ON law.files
  FOR EACH ROW EXECUTE FUNCTION law.reject_scope_change('case_id', 'uploaded_by');
CREATE TRIGGER conversations_scope_immutable BEFORE UPDATE ON law.ai_conversations
  FOR EACH ROW EXECUTE FUNCTION law.reject_scope_change('user_id', 'case_id', 'mode');
CREATE TRIGGER messages_scope_immutable BEFORE UPDATE ON law.ai_messages
  FOR EACH ROW EXECUTE FUNCTION law.reject_scope_change('conversation_id', 'case_id', 'role');
CREATE TRIGGER chunks_scope_immutable BEFORE UPDATE ON law.doc_chunks
  FOR EACH ROW EXECUTE FUNCTION law.reject_scope_change('file_id', 'case_id');

-- MATCH SIMPLE 在 case_id=NULL 时跳过复合 FK，因此额外使用 NULL 安全比较。
CREATE FUNCTION law.validate_message_scope() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, law AS $$
DECLARE
  conversation_case_id bigint;
BEGIN
  SELECT case_id INTO conversation_case_id FROM law.ai_conversations
    WHERE id = NEW.conversation_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '会话不存在' USING ERRCODE = '23503';
  END IF;
  IF NEW.case_id IS DISTINCT FROM conversation_case_id THEN
    RAISE EXCEPTION '消息案件归属必须与会话一致' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER messages_validate_scope BEFORE INSERT OR UPDATE ON law.ai_messages
  FOR EACH ROW EXECUTE FUNCTION law.validate_message_scope();

CREATE FUNCTION law.validate_message_attachment() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, law AS $$
DECLARE
  message_case_id bigint;
  message_role text;
  conversation_user_id bigint;
  file_case_id bigint;
  file_uploader_id bigint;
BEGIN
  SELECT m.case_id, m.role, c.user_id INTO message_case_id, message_role, conversation_user_id
    FROM law.ai_messages m JOIN law.ai_conversations c ON c.id = m.conversation_id
    WHERE m.id = NEW.message_id FOR KEY SHARE OF m, c;
  IF NOT FOUND THEN
    RAISE EXCEPTION '附件所属消息不存在' USING ERRCODE = '23503';
  END IF;
  SELECT case_id, uploaded_by INTO file_case_id, file_uploader_id
    FROM law.files WHERE id = NEW.file_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '附件文件不存在' USING ERRCODE = '23503';
  END IF;
  IF message_role <> 'user' OR NEW.case_id IS DISTINCT FROM message_case_id
    OR NEW.case_id IS DISTINCT FROM file_case_id THEN
    RAISE EXCEPTION '附件仅可关联同案件范围的用户消息' USING ERRCODE = '23514';
  END IF;
  IF NEW.case_id IS NULL AND file_uploader_id IS DISTINCT FROM conversation_user_id THEN
    RAISE EXCEPTION '助手附件上传人必须为会话所有者' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER message_files_validate_scope BEFORE INSERT OR UPDATE ON law.ai_message_files
  FOR EACH ROW EXECUTE FUNCTION law.validate_message_attachment();

-- 提交时保证组织 owner 恰好是对应的 active owner 成员，支持同一事务内建组织/转让。
CREATE FUNCTION law.validate_organization_owner() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, law AS $$
DECLARE
  org_ids bigint[];
  org_to_check bigint;
  owner_to_check bigint;
BEGIN
  IF TG_TABLE_NAME = 'organizations' THEN
    org_ids := CASE WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.id] ELSE ARRAY[NEW.id] END;
  ELSIF TG_OP = 'INSERT' THEN
    org_ids := ARRAY[NEW.org_id];
  ELSIF TG_OP = 'DELETE' THEN
    org_ids := ARRAY[OLD.org_id];
  ELSE
    org_ids := ARRAY[OLD.org_id, NEW.org_id];
  END IF;
  FOREACH org_to_check IN ARRAY org_ids LOOP
    SELECT owner_user_id INTO owner_to_check FROM law.organizations
      WHERE id = org_to_check FOR UPDATE;
    IF FOUND AND NOT EXISTS (
      SELECT 1 FROM law.organization_members
      WHERE org_id = org_to_check AND user_id = owner_to_check AND role = 'owner' AND status = 'active'
    ) THEN
      RAISE EXCEPTION '组织 % 的所有者必须是有效 owner 成员', org_to_check USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER organizations_validate_owner
  AFTER INSERT OR UPDATE ON law.organizations DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION law.validate_organization_owner();
CREATE CONSTRAINT TRIGGER members_validate_owner
  AFTER INSERT OR UPDATE OR DELETE ON law.organization_members DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION law.validate_organization_owner();

-- 业务审核/删除只改变状态，审计表禁止修改、删除或清空已有记录。
CREATE FUNCTION law.reject_audit_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '审计日志只允许追加' USING ERRCODE = '23514';
END;
$$;
CREATE TRIGGER audit_logs_append_only BEFORE UPDATE OR DELETE OR TRUNCATE ON law.audit_logs
  FOR EACH STATEMENT EXECUTE FUNCTION law.reject_audit_mutation();

COMMIT;
